#################################################################
#### STAGE: ORA_ACVW_FLEXCUBE
## Operator
pxbridge
## Operator options
-Orientation link
-XMLProperties '<?xml version=\'1.0\' encoding=\'UTF-16\'?><Properties version=\'1.1\'><Common><Context type=\'int\'>1</Context><Variant type=\'string\'>11</Variant><DescriptorVersion type=\'string\'>1.0</DescriptorVersion><PartitionType type=\'int\'>-1</PartitionType><RCP type=\'int\'>0</RCP></Common><Connection><Server modified=\'1\' type=\'string\'><![CDATA[[&"PSET_ADMFCPGG.$VAG_ORA_URI_ADMFCPGG"]]]></Server><Username modified=\'1\' type=\'string\'><![CDATA[[&"PSET_ADMFCPGG.$VAG_ORA_USU_ADMFCPGG"]]]></Username><Password modified=\'1\' type=\'string\'><![CDATA[[&"PSET_ADMFCPGG.$VAG_ORA_PASS_ADMFCPGG"]]]></Password><OSLevelAuthentication type=\'bool\'><![CDATA[0]]></OSLevelAuthentication><Version type=\'string\'><![CDATA[11g]]></Version></Connection><Usage><ReadMode type=\'int\'><![CDATA[0]]></ReadMode><GenerateSQL type=\'bool\'><![CDATA[0]]></GenerateSQL><EnableQuotedIDs type=\'bool\'><![CDATA[0]]></EnableQuotedIDs><SQL><SelectStatement modified=\'1\' type=\'string\'><![CDATA[SELECT   

	ACC.ACCOUNT_TYPE STR_CODIGO_TIPO_CUENTA,
	CASE WHEN ACC.ACCOUNT_TYPE = \'U\' THEN \'CUENTA CORRIENTE\' WHEN ACC.ACCOUNT_TYPE = \'S\' THEN \'CUENTA AHORROS\' END STR_TIPO_PRODUCTO,
	DRT.TXN_ACC NUM_NUMERO_PRODUCTO,
	DRT.TRN_DT DTM_FECHA_TRANSFERENCIA,
	TRIM(SUBSTR(CUS.UNIQUE_ID_VALUE, 1, 50))ID_RECAUDADOR,
	SUBSTR(UFL.FIELD_VAL_14, 5) NUM_PRODUCTO_ORIGINADOR,
	UFL.PRODUCT_CODE STR_DIM_TTP_TIPO_TRANSA_PSV_NK,
	TRIM(SUBSTR(BP.BANK_CODE, 1, 10)) STR_DIM_TER_COD_BANCO_NK,
	TRIM(SUBSTR(BP.BANK_NAME, 1, 50)) STR_ENTIDAD_FINANCIERA,


TO_CHAR (DRT.LCY_AMOUNT   , \'99G999G999G999G999D99\')  NUM_VALOR_TRANSACCION,
DRT.TRN_REF_NO AS  STR_REFERENCIAFC
FROM	FCJADM.CSTM_CONTRACT_USERDEF_FIELDS UFL,
		FCJADM.DETB_RTL_TELLER DRT,
		FCJADM.STTM_CUST_ACCOUNT ACC,
		FCJADM.PCTM_BANK_PARAM BP,
		FCJADM.STTM_CUSTOMER CUS,
		FCJADM_PR.FC_SAM_AGR_TBL_AGRUPACIONES FC_SAM_AGR_TBL_AGRUPACIONES,
		FCJADM_PR.FC_SAM_AGR_TBL_DETALLES_AGRUP FC_SAM_AGR_TBL_DETALLES_AGRUP
WHERE (DRT.TRN_DT = TO_DATE(\'[&"VAP_FEC_FIN"]\',\'YYYYMMDD\'))
	AND (ACC.CUST_AC_NO IN (\'[&"VAP_ARR_NUM_CTA"]\'))
	AND (ACC.ACCOUNT_TYPE IN (\'[&"VAP_ARR_TIPO_CTA_DESTINO"]\'))
	AND (BP.BANK_CODE = NVL(TRIM(replace(\'[&"VAP_COD_ENTIDAD_ORIG"]\',\'TODOS\',\'\')), BP.BANK_CODE))
	AND (LTRIM(SUBSTR(UFL.FIELD_VAL_14, 5),\'0\') = NVL(LTRIM(TRIM(\'[&"VAP_NUM_CTA_ORIG"]\'),\'0\'), LTRIM(SUBSTR(UFL.FIELD_VAL_14, 5),\'0\')))
	AND (FC_SAM_AGR_TBL_AGRUPACIONES.STR_NOMBRE = \'179_PRODUCTOS_TRANSFERENCIAS_AVAL\')
	AND (UFL.CONTRACT_REF_NO=DRT.TRN_REF_NO)
	AND (ACC.CUST_AC_NO=DRT.TXN_ACC)
	AND (BP.BANK_CODE = SUBSTR(UFL.FIELD_VAL_14, 1, 4))
	AND (CUS.CUSTOMER_NO=ACC.CUST_NO)
	AND (FC_SAM_AGR_TBL_AGRUPACIONES.NUM_ID_AGRUPACION=FC_SAM_AGR_TBL_DETALLES_AGRUP.NUM_ID_AGRUPACION)
	AND (FC_SAM_AGR_TBL_DETALLES_AGRUP.STR_VALOR=UFL.PRODUCT_CODE)]]><ReadFromFileSelect type=\'bool\'><![CDATA[0]]></ReadFromFileSelect><Tables collapsed=\'1\'></Tables><Parameters collapsed=\'1\'></Parameters><Columns collapsed=\'1\'></Columns></SelectStatement></SQL><EnablePartitionedReads collapsed=\'1\' modified=\'1\' type=\'bool\'><![CDATA[0]]></EnablePartitionedReads><Transaction><IsolationLevel modified=\'1\' type=\'int\'><![CDATA[2]]></IsolationLevel><RecordCount type=\'int\'><![CDATA[2000]]></RecordCount><EndOfWave type=\'int\'><![CDATA[0]]></EndOfWave></Transaction><Session><ArraySize type=\'int\'><![CDATA[2000]]></ArraySize><PrefetchRowCount type=\'int\'><![CDATA[1]]></PrefetchRowCount><PrefetchMemorySize type=\'int\'><![CDATA[0]]></PrefetchMemorySize><PassLobLocator collapsed=\'1\' type=\'bool\'><![CDATA[0]]></PassLobLocator><BFILEasBLOB type=\'bool\'><![CDATA[0]]></BFILEasBLOB><TreatWarningsAsErrors type=\'bool\'><![CDATA[0]]></TreatWarningsAsErrors><TreatFetchTruncateAsError type=\'bool\'><![CDATA[1]]></TreatFetchTruncateAsError></Session><BeforeAfter collapsed=\'1\' type=\'bool\'><![CDATA[0]]></BeforeAfter><ApplicationFailoverControl collapsed=\'1\' type=\'bool\'><![CDATA[0]]></ApplicationFailoverControl><LimitRows collapsed=\'1\' type=\'bool\'><![CDATA[0]]></LimitRows></Usage></Properties >'
-connector '{
   name=OracleConnector, 
   library=ccora11g, 
   version=1.0, 
   versionlist=\'1.0,1.0\', 
   variant=\'11\', 
   variantlist=\'V1;11:"11g":ccora11g;12:"12c":ccora12c\'
}'
-source 0 '{
      DSSQLType={STR_CODIGO_TIPO_CUENTA=12, STR_TIPO_PRODUCTO=12, NUM_NUMERO_PRODUCTO=12, DTM_FECHA_TRANSFERENCIA=9, ID_RECAUDADOR=12, NUM_PRODUCTO_ORIGINADOR=12, STR_DIM_TTP_TIPO_TRANSA_PSV_NK=12, STR_DIM_TER_COD_BANCO_NK=12, STR_ENTIDAD_FINANCIERA=12, NUM_VALOR_TRANSACCION=12, STR_REFERENCIAFC=12}, 
      DSSQLPrecision={STR_CODIGO_TIPO_CUENTA=10, STR_TIPO_PRODUCTO=50, NUM_NUMERO_PRODUCTO=30, ID_RECAUDADOR=50, NUM_PRODUCTO_ORIGINADOR=20, STR_DIM_TTP_TIPO_TRANSA_PSV_NK=10, STR_DIM_TER_COD_BANCO_NK=10, STR_ENTIDAD_FINANCIERA=50, NUM_VALOR_TRANSACCION=22, STR_REFERENCIAFC=16}, 
      DSSchema=\'record
         (
           STR_CODIGO_TIPO_CUENTA\:nullable string\[max\=10\]\;
           STR_TIPO_PRODUCTO\:nullable string\[max\=50\]\;
           NUM_NUMERO_PRODUCTO\:nullable string\[max\=30\]\;
           DTM_FECHA_TRANSFERENCIA\:nullable date\;
           ID_RECAUDADOR\:nullable string\[max\=50\]\;
           NUM_PRODUCTO_ORIGINADOR\:nullable string\[max\=20\]\;
           STR_DIM_TTP_TIPO_TRANSA_PSV_NK\:nullable string\[max\=10\]\;
           STR_DIM_TER_COD_BANCO_NK\:nullable string\[max\=10\]\;
           STR_ENTIDAD_FINANCIERA\:nullable string\[max\=50\]\;
           NUM_VALOR_TRANSACCION\:nullable string\[max\=22\]\;
           STR_REFERENCIAFC\:nullable string\[max\=16\]\;
         )\'
}'


## General options
[ident('ORA_ACVW_FLEXCUBE'); jobmon_ident('ORA_ACVW_FLEXCUBE')]
## Outputs
0> [modify (
  STR_CODIGO_TIPO_CUENTA:nullable string[max=10]=STR_CODIGO_TIPO_CUENTA;
  STR_TIPO_PRODUCTO:nullable string[max=50]=STR_TIPO_PRODUCTO;
  NUM_NUMERO_PRODUCTO:nullable string[max=30]=NUM_NUMERO_PRODUCTO;
  DTM_FECHA_TRANSFERENCIA:nullable date=DTM_FECHA_TRANSFERENCIA;
  ID_RECAUDADOR:nullable string[max=50]=ID_RECAUDADOR;
  NUM_PRODUCTO_ORIGINADOR:nullable string[max=20]=NUM_PRODUCTO_ORIGINADOR;
  STR_DIM_TTP_TIPO_TRANSA_PSV_NK:nullable string[max=10]=STR_DIM_TTP_TIPO_TRANSA_PSV_NK;
  STR_DIM_TER_COD_BANCO_NK:nullable string[max=10]=STR_DIM_TER_COD_BANCO_NK;
  STR_ENTIDAD_FINANCIERA:nullable string[max=50]=STR_ENTIDAD_FINANCIERA;
  NUM_VALOR_TRANSACCION:nullable string[max=22]=NUM_VALOR_TRANSACCION;
  STR_REFERENCIAFC:nullable string[max=16]=STR_REFERENCIAFC;
keep
  STR_CODIGO_TIPO_CUENTA,STR_TIPO_PRODUCTO,NUM_NUMERO_PRODUCTO,DTM_FECHA_TRANSFERENCIA,
  ID_RECAUDADOR,NUM_PRODUCTO_ORIGINADOR,STR_DIM_TTP_TIPO_TRANSA_PSV_NK,STR_DIM_TER_COD_BANCO_NK,
  STR_ENTIDAD_FINANCIERA,NUM_VALOR_TRANSACCION,STR_REFERENCIAFC;
)] 'ORA_ACVW_FLEXCUBE:LNK_ORA_FLEXCUBE.v'
;

