#################################################################
#### STAGE: ORA_ACVW_FLEXCUBE
## Operator
pxbridge
## Operator options
-Orientation link
-XMLProperties '<?xml version=\'1.0\' encoding=\'UTF-16\'?><Properties version=\'1.1\'><Common><Context type=\'int\'>1</Context><Variant type=\'string\'>11</Variant><DescriptorVersion type=\'string\'>1.0</DescriptorVersion><PartitionType type=\'int\'>-1</PartitionType><RCP type=\'int\'>0</RCP></Common><Connection><Server modified=\'1\' type=\'string\'><![CDATA[[&"PSET_ADMFCP.$VAG_ORA_URI_ADMFCP"]]]></Server><Username modified=\'1\' type=\'string\'><![CDATA[[&"PSET_ADMFCP.$VAG_ORA_USU_ADMFCP"]]]></Username><Password modified=\'1\' type=\'string\'><![CDATA[[&"PSET_ADMFCP.$VAG_ORA_PASS_ADMFCP"]]]></Password><OSLevelAuthentication type=\'bool\'><![CDATA[0]]></OSLevelAuthentication><Version type=\'string\'><![CDATA[11g]]></Version></Connection><Usage><ReadMode type=\'int\'><![CDATA[0]]></ReadMode><GenerateSQL type=\'bool\'><![CDATA[0]]></GenerateSQL><EnableQuotedIDs type=\'bool\'><![CDATA[0]]></EnableQuotedIDs><SQL><SelectStatement modified=\'1\' type=\'string\'><![CDATA[SELECT
	ACD.ACCOUNT_TYPE AS STR_CODIGO_TIPO_CUENTA,
	CASE WHEN ACD.ACCOUNT_TYPE = \'U\' THEN \'CUENTA CORRIENTE\' WHEN ACD.ACCOUNT_TYPE = \'S\' THEN \'CUENTA AHORROS\' END AS STR_TIPO_PRODUCTO,
	DRT.OFS_ACC NUM_NUMERO_PRODUCTO,
	DRT.TRN_DT DTM_FECHA_TRANSFERENCIA,
	TRIM(SUBSTR(CUS.UNIQUE_ID_VALUE, 1, 50)) ID_RECAUDADOR,
	DRT.TXN_ACC NUM_PRODUCTO_ORIGINADOR,
	DRT.PRODUCT_CODE STR_DIM_TTP_TIPO_TRANSA_PSV_NK,
	\'0023\' STR_DIM_TER_COD_BANCO_NK,
	\'BANCO DE OCCIDENTE\' STR_ENTIDAD_FINANCIERA,

TO_CHAR (  DRT.LCY_AMOUNT    , \'99G999G999G999G999D99\')  NUM_VALOR_TRANSACCION,
      DRT.TRN_REF_NO AS  STR_REFERENCIAFC   
FROM	FCJADM.DETB_RTL_TELLER DRT,
		FCJADM.STTM_CUST_ACCOUNT ACO,
		FCJADM.STTM_CUST_ACCOUNT ACD,
		FCJADM.STTM_CUSTOMER CUS,
		FCJADM.ACTB_DAILY_LOG DLG,
		FCJADM_PR.FC_SAM_AGR_TBL_AGRUPACIONES FC_SAM_AGR_TBL_AGRUPACIONES,
		FCJADM_PR.FC_SAM_AGR_TBL_DETALLES_AGRUP FC_SAM_AGR_TBL_DETALLES_AGRUP
WHERE	(DLG.ENTRY_SEQ_NO = 1)
	AND (ACD.CUST_AC_NO IN (\'[&"VAP_ARR_NUM_CTA"]\')) 
